const routes = [
  ['overview','Overview','home'],['accounts','Accounts','wallet'],['transactions','Transactions','arrows'],['budget','Budget','chart'],['bills','Bills','receipt'],['goals','Goals','target'],['investments','Investments','trend'],['net-worth','Net Worth','diamond'],['reports','Reports','report'],['calendar','Calendar','calendar'],['loans','Loans','loan'],['settings','Settings','settings']
];
const esc = (value = '') => String(value).replace(/[&<>'"]/g, (char) => ({ '&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;' }[char]));
const get = (resource, id) => data[resource]?.find((item) => item.id === id);
