const periodRangeLabel = () => { const bounds=periodBounds(),format=new Intl.DateTimeFormat(data.settings.locale,{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}); return `${format.format(new Date(`${bounds.from}T12:00:00Z`))} – ${format.format(new Date(`${bounds.to}T12:00:00Z`))}`; };
