const download = (name, content, type = 'application/json') => { const link = document.createElement('a'); link.href = URL.createObjectURL(new Blob([content], { type })); link.download = name; link.click(); URL.revokeObjectURL(link.href); };
const empty = (label) => `<div class="empty"><div class="avatar" style="margin:auto">＋</div><p>No ${esc(label)} yet.<br><span class="small">Add one to begin tracking.</span></p></div>`;
