const sorted = (items,page,values={}) => { const state=sortState[page]; return items.slice().sort((a,b)=>(state.direction==='asc'?1:-1)*compare(values[state.key]?.(a) ?? a[state.key],values[state.key]?.(b) ?? b[state.key])); };
const sortButton = (page,key,label) => { const state=sortState[page],active=state.key===key; return `<button class="sort-button ${active?'active':''}" data-sort-page="${page}" data-sort-key="${key}">${esc(label)} <span aria-hidden="true">${active?(state.direction==='asc'?'↑':'↓'):'↕'}</span></button>`; };
const sortSelect = (page,options) => `<label class="sort-select">Sort by <select data-list-sort="${page}">${options.map(([value,label])=>`<option value="${value}" ${sortState[page].key===value?'selected':''}>${esc(label)}</option>`).join('')}</select></label><button class="button icon-button sort-direction" data-list-direction="${page}" aria-label="Reverse sort order">${sortState[page].direction==='asc'?'↑':'↓'}</button>`;
