const card = (body, cls = '') => `<section class="card ${cls}">${body}</section>`;
const field = (label, name, type = 'text', value = '', options = []) => `<div class="field"><label for="f-${name}">${esc(label)}</label>${type === 'select' ? `<select id="f-${name}" name="${name}" required>${options.map(([v,l]) => `<option value="${esc(v)}" ${String(v) === String(value) ? 'selected' : ''}>${esc(l)}</option>`).join('')}</select>` : `<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${type === 'number' ? 'step="0.01"' : ''} required>`}</div>`;
const icon = (name) => { const paths={home:'<path d="M3 11.5 12 4l9 7.5V21h-6v-6H9v6H3Z"/>',wallet:'<path d="M3 6h16v14H3zM16 10h5v6h-5a3 3 0 0 1 0-6Z"/>',arrows:'<path d="m7 7 3-3 3 3M10 4v12M17 17l-3 3-3-3M14 20V8"/>',chart:'<path d="M4 20V10m6 10V4m6 16v-7m4 7H2"/>',receipt:'<path d="M5 3h14v19l-3-2-4 2-4-2-3 2Zm4 5h6M9 12h6"/>',target:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/>',trend:'<path d="m4 17 6-6 4 4 6-8M15 7h5v5"/>',diamond:'<path d="m12 3 9 7-9 11-9-11Z"/>',report:'<path d="M5 3h14v18H5zm4 5h6m-6 4h6m-6 4h4"/>',calendar:'<path d="M4 5h16v16H4zM8 2v6m8-6v6M4 10h16"/>',loan:'<path d="M3 8h18M5 8v10m5-10v10m5-10v10m4-10v10M3 21h18M12 3 3 8h18Z"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19 13.5v-3l-2-.7-.8-1.8.9-1.9L15 4l-1.9.9-1.8-.8L10.5 2h-3l-.7 2.1-1.8.8L3.1 4 1 6.1 1.9 8l-.8 1.8-2.1.7v3l2.1.7.8 1.8-1 1.9L3 20l2-.9 1.8.8.7 2.1h3l.8-2.1 1.8-.8 1.9.9 2.1-2.1-.9-1.9.8-1.8Z"/>'};return `<svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${paths[name]||paths.home}</svg>`; };
const addTransactionMenu = () => `<details class="action-menu"><summary class="button primary">＋ Add transaction <span aria-hidden="true">⌄</span></summary><div class="action-menu-popover" role="menu"><button type="button" data-add="transactions" role="menuitem"><strong>Manual entry</strong><span>Enter transaction details</span></button><button type="button" data-action="sms-import" role="menuitem"><strong>Banking SMS</strong><span>Paste and review a bank message</span></button></div></details>`;
const transactionsForMonth = (month) => { const bounds=financialPeriod(month,data.settings.monthStart);return data.transactions.filter((t)=>{const date=String(t.date||'').slice(0,10);return date>=bounds.from&&date<=bounds.to;}); };
const monthlyHistory = (count=6) => Array.from({length:count},(_,index)=>reportingMonthOffset(selectedMonth,index-count+1)).map((month)=>{const transactions=transactionsForMonth(month),flow=cashFlow(transactions);return {month,label:monthLabel(month),income:flow.income,expenses:flow.expenses,surplus:flow.income-flow.expenses,savings:savingsRateMinor(flow)};});
const changeLabel = (current,previous,invert=false) => { if(previous===0n)return null;const change=periodChange(current,previous),positive=invert?change.amount<=0n:change.amount>=0n;return `<span class="trend ${positive?'':'negative'}">${change.amount>=0n?'+':''}${pct(change.percent)} vs prior</span>`; };
const sparkline = (values,label) => { if(values.length<2)return '';const numbers=values.map(Number),min=Math.min(...numbers),max=Math.max(...numbers),range=max-min||1,points=numbers.map((value,index)=>`${(index/(numbers.length-1))*100},${32-((value-min)/range)*28}`).join(' ');return `<svg class="spark" viewBox="0 0 100 36" role="img" aria-label="${esc(label)}"><polyline points="${points}"/></svg>`; };
const quickAdd = () => `<details class="quick-add"><summary aria-label="Quick add">＋</summary><div class="quick-add-menu"><strong>Quick add</strong><button data-add="transactions" data-transaction-type="expense">Expense</button><button data-add="transactions" data-transaction-type="income">Income</button><button data-add="transactions" data-transaction-type="transfer">Transfer</button><button data-add="bills">Bill</button><button data-add="goals">Goal</button><button data-add="holdings">Investment</button></div></details>`;

function applyTheme() {
  const setting = data.settings.theme;
  const dark = setting === 'dark' || (setting === 'system' && matchMedia('(prefers-color-scheme: dark)').matches);
  document.documentElement.dataset.theme = dark ? 'dark' : 'light';
}
function shell(page) {
  const navGroups=[['Core',['overview','accounts','transactions','budget']],['Plan',['bills','goals','loans','calendar']],['Grow',['investments','net-worth']],['Insights',['reports','assistant']],['Manage',['settings']]];
  const available=routes.concat([['assistant','AI Assistant','trend']]);
  const nav=navGroups.map(([group,keys])=>`<div class="nav-group"><p>${group}</p>${keys.map(key=>available.find(item=>item[0]===key)).filter(Boolean).map(([key,label,iconName]) => `<a href="#/${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}><span class="nav-icon">${icon(iconName)}</span>${label}</a>`).join('')}</div>`).join('');
  const showPeriod=!['settings','accounts','goals','investments','net-worth','loans'].includes(page),primary={overview:addTransactionMenu(),transactions:addTransactionMenu(),budget:'<button class="button primary" data-add="budgets">＋ Add budget</button>',accounts:'<button class="button primary" data-add="accounts">＋ Add account</button>',bills:'<button class="button primary" data-add="bills">＋ Add bill</button>'}[page]||'';
  const period=showPeriod?`<div class="period-picker" aria-label="Reporting period"><button class="button icon-button" data-action="previous-month" aria-label="Previous month">‹</button><label class="month-control"><span>${esc(periodLabel())}</span><input id="period-month" type="month" value="${selectedMonth}" aria-label="Reporting month"></label><button class="button icon-button" data-action="next-month" aria-label="Next month">›</button></div>`:'';
  const mobileMenu=`<header class="mobile-header"><a class="mobile-brand" href="#/overview" aria-label="Quiet Ledger overview"><img class="brand-mark" src="./assets/quiet-ledger-icon.svg" alt=""><span>Quiet Ledger</span></a><details class="mobile-menu"><summary aria-label="Open navigation"><span>${esc(title(page))}</span><svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M4 7h16M4 12h16M4 17h16"/></svg></summary><div class="mobile-menu-panel"><div class="mobile-menu-heading"><div><span class="eyebrow">Navigation</span><strong>All pages</strong></div><span class="mobile-menu-close" aria-hidden="true">×</span></div><nav class="nav" aria-label="Mobile navigation">${nav}</nav></div></details></header>`;
  app.innerHTML = `<div class="shell"><aside class="sidebar"><div class="brand"><img class="brand-mark" src="./assets/quiet-ledger-icon.svg" alt="">Quiet Ledger</div><nav class="nav" aria-label="Primary">${nav}</nav></aside>${mobileMenu}<main class="content" id="main"><header class="topbar"><div>${page==='overview'?`<p class="eyebrow">${new Intl.DateTimeFormat(data.settings.locale,{weekday:'long',month:'long',day:'numeric'}).format(new Date())}</p>`:''}<h1>${esc(title(page))}</h1></div><div class="actions">${period}${primary}</div></header>${showPeriod?`<div class="period-context"><span class="badge">${esc(periodRangeLabel())}</span>${selectedMonth!==new Date().toISOString().slice(0,7)?'<button class="button small" data-action="current-month">Current period</button>':''}</div>`:''}<div id="page">${renderPage(page)}</div></main>${quickAdd()}</div>`;
}
function summaryMetrics() {
  const cf = cashFlow(periodTransactions()); const worth = netWorth(data.accounts, data.settings.rates);
  const assets = data.accounts.filter((a) => a.group === 'asset' && a.includeNetWorth).reduce((s,a) => s + money(a.balance), 0n);
  const debt = data.accounts.filter((a) => a.group === 'liability' && a.includeNetWorth).reduce((s,a) => s + money(a.balance), 0n);
  const investments = data.holdings.reduce((s,h) => s + investmentGain(h.quantity,h.averageCost,h.currentPrice).value, 0n);
  return { 'net-worth':['Net Worth',worth], cash:['Cash & Bank',assets], investments:['Investments',investments], debt:['Total Debt',debt], income:['Monthly Income',cf.income], expenses:['Monthly Expenses',cf.expenses], surplus:['Monthly Surplus',cf.income-cf.expenses], 'savings-rate':['Savings Rate',savingsRateMinor(cf),true] };
}
const savingsRateMinor = (cf) => cf.income ? ratio(cf.income - cf.expenses, cf.income) : 0n;
function cashFlowWaterfall(cf) { const remaining=cf.income-cf.expenses,max=cf.income>cf.expenses?cf.income:cf.expenses||1n,incomeWidth=Number(ratio(cf.income,max))/100,expenseWidth=Number(ratio(cf.expenses,max))/100,remainingWidth=Math.abs(Number(ratio(remaining,max)))/100;return `<div class="waterfall" role="img" aria-label="Income ${fmt(cf.income)}, less expenses ${fmt(cf.expenses)}, equals ${fmt(remaining)} remaining"><div><span>Income</span><i class="waterfall-income" style="width:${incomeWidth}%"></i><strong>${fmt(cf.income)}</strong></div><div><span>Expenses</span><i class="waterfall-expense" style="width:${expenseWidth}%"></i><strong>−${fmt(cf.expenses)}</strong></div><div class="waterfall-total"><span>${remaining<0n?'Shortfall':'Available'}</span><i class="${remaining<0n?'waterfall-expense':'waterfall-surplus'}" style="width:${remainingWidth}%"></i><strong class="${remaining<0n?'expense':'income'}">${fmt(remaining)}</strong></div></div>`; }
function financialInsights(cf,previous) { const items=[],uncategorized=data.transactions.filter(t=>inPeriod(t)&&!t.categoryId&&t.type!=='transfer').length,overdue=data.bills.filter(b=>!b.paid&&b.dueDate<new Date().toISOString().slice(0,10)).length,overspent=data.budgets.filter(b=>b.period===selectedMonth&&periodTransactions().filter(t=>t.categoryId===b.categoryId&&t.type==='expense').reduce((sum,t)=>sum+money(t.amount),0n)>money(b.amount)).length;if(previous&&previous.expenses>0n){const change=periodChange(cf.expenses,previous.expenses);items.push({icon:change.amount>0n?'↗':'↘',tone:change.amount>0n?'warning':'healthy',title:`Spending ${change.amount>0n?'increased':'decreased'} ${pct(change.percent<0n?-change.percent:change.percent)}`,detail:`Compared with ${previous.label}, expenses changed by ${fmt(change.amount<0n?-change.amount:change.amount)}.`});}if(overspent)items.push({icon:'!',tone:'warning',title:`${overspent} budget${overspent===1?' is':'s are'} over plan`,detail:'Review the affected categories before making further discretionary purchases.'});if(overdue)items.push({icon:'!',tone:'warning',title:`${overdue} overdue bill${overdue===1?'':'s'}`,detail:'Mark paid, edit, or skip these bills to keep the forecast accurate.'});if(uncategorized)items.push({icon:'?',tone:'warning',title:`${uncategorized} uncategorized transaction${uncategorized===1?'':'s'}`,detail:'Categorizing these improves reports and budget comparisons.'});if(cf.income>0n)items.push({icon:'✓',tone:savingsRateMinor(cf)>=2000n?'healthy':'neutral',title:`Savings rate is ${pct(savingsRateMinor(cf))}`,detail:`${fmt(cf.income-cf.expenses)} remains after cleared income and expenses this period.`});if(!items.length)items.push({icon:'✓',tone:'healthy',title:'Your records look healthy',detail:'No overdue bills, overspent budgets, or uncategorized activity were found.'});return items.slice(0,5); }
function overview() {
  const metrics = summaryMetrics(); const widgets = data.widgets.length ? data.widgets : Object.keys(metrics);
  const cf = cashFlow(periodTransactions()); const total = cf.expenses;
  const history=monthlyHistory(),previous=history.at(-2),metricHistory={income:history.map(x=>x.income),expenses:history.map(x=>x.expenses),surplus:history.map(x=>x.surplus),'savings-rate':history.map(x=>x.savings)};
  const spending = data.categories.filter((c) => c.type === 'expense').map((c) => ({ ...c, spent: periodTransactions().filter((t) => t.categoryId === c.id && t.type === 'expense').reduce((s,t) => s + money(t.amount),0n) })).filter((c) => c.spent > 0n);
  const insights=financialInsights(cf,previous);
  return `<div class="grid summary-grid">${widgets.map((key) => { const item=metrics[key];if(!item)return '';const value=key==='debt'&&item[1]===0n?'No debt':item[2]?pct(item[1]):fmt(item[1]),prior=previous?.[key==='savings-rate'?'savings':key];return card(`<span class="metric-label">${item[0]}</span><div class="metric"><strong>${value}</strong>${typeof prior==='bigint'?changeLabel(item[1],prior,key==='expenses'):''}</div>${metricHistory[key]?.some(Boolean)?sparkline(metricHistory[key],`${item[0]} over six months`):''}`); }).join('')}</div>
  <div class="grid two-col">${card(`<div class="section-head"><div><h2>Cash flow</h2><span class="small muted">${esc(periodRangeLabel())}</span></div><span class="badge healthy">${pct(savingsRateMinor(cf))} retained</span></div>${cashFlowWaterfall(cf)}`,'cash-flow-card')}
  ${card(`<div class="section-head"><div><h2>Financial insights</h2><span class="small muted">Based on your actual records</span></div><span class="badge ${insights.some(i=>i.tone==='warning')?'warning':'healthy'}">${insights.length}</span></div><div class="insights-list">${insights.map(item=>`<div class="insight ${item.tone}"><span>${item.icon}</span><div><strong>${esc(item.title)}</strong><p>${esc(item.detail)}</p></div></div>`).join('')}</div>`)}</div>
  <div class="grid two-col">${card(`<div class="section-head"><h2>Spending by category</h2><a class="button small" href="#/reports">View report</a></div>${spending.length ? spending.sort((a,b)=>compare(b.spent,a.spent)).slice(0,5).map((c) => `<div class="bar-row category-row"><span><i class="category-dot" style="background:${esc(c.color)}"></i>${esc(c.name)}</span>${progress(Number(ratio(c.spent,total))/100)}<strong>${fmt(c.spent)}</strong></div>`).join('') : empty('spending')}`)}${card(`<div class="section-head"><h2>Budget progress</h2><a class="button small" href="#/budget">Manage</a></div>${budgetRows(true)}`)}</div>
  <div class="grid two-col">${card(`<div class="section-head"><h2>Goals</h2><a class="small muted" href="#/goals">See all</a></div>${goalCards(true)}`)}${card(`<div class="section-head"><h2>Upcoming bills</h2><a class="small muted" href="#/bills">See all</a></div>${billList(true)}`)}</div>`;
}
function transactionTable(items) { const rows=sorted(items,'transactions',{description:(t)=>t.merchant||t.description,account:(t)=>get('accounts',t.accountId)?.name,category:(t)=>get('categories',t.categoryId)?.name,amount:(t)=>money(t.amount)}); if(!rows.length)return empty('transactions'); const pages=Math.ceil(rows.length/transactionPageSize);transactionPage=Math.min(Math.max(1,transactionPage),pages);const start=(transactionPage-1)*transactionPageSize,visible=rows.slice(start,start+transactionPageSize);return `<div class="table-wrap"><table><thead><tr><th>${sortButton('transactions','date','Date')}</th><th>${sortButton('transactions','description','Description')}</th><th>${sortButton('transactions','account','Account')}</th><th>${sortButton('transactions','category','Category')}</th><th>${sortButton('transactions','status','Status')}</th><th>${sortButton('transactions','amount','Amount')}</th><th><span class="visually-hidden">Actions</span></th></tr></thead><tbody>${visible.map((t) => `<tr><td>${esc(t.date)}</td><td><strong>${esc(t.merchant || t.description)}</strong><div class="item-meta">${esc(t.description)}</div><div class="transaction-mobile-meta" aria-hidden="true">${esc(t.date)} · ${esc(get('accounts',t.accountId)?.name || 'No account')} · ${esc(get('categories',t.categoryId)?.name || 'Uncategorized')}</div></td><td>${esc(get('accounts',t.accountId)?.name || '—')}</td><td>${esc(get('categories',t.categoryId)?.name || 'Uncategorized')}</td><td><span class="badge">${esc(t.status)}</span></td><td class="amount ${t.type}">${t.type === 'expense' ? '−' : t.type === 'transfer' ? '' : '+'}${amt(t.amount,t.currency)}</td><td>${overflowMenu('transactions',t.id,t.merchant||t.description)}</td></tr>`).join('')}</tbody></table></div><div class="pagination"><span class="small muted">${start+1}–${Math.min(start+transactionPageSize,rows.length)} of ${rows.length}</span><label>Rows <select id="transaction-page-size">${[10,25,50].map((size)=>`<option value="${size}" ${transactionPageSize===size?'selected':''}>${size}</option>`).join('')}</select></label><div class="actions"><button class="button small" data-action="transaction-page" data-page="${transactionPage-1}" ${transactionPage===1?'disabled':''}>Previous</button><span class="small">Page ${transactionPage} of ${pages}</span><button class="button small" data-action="transaction-page" data-page="${transactionPage+1}" ${transactionPage===pages?'disabled':''}>Next</button></div></div>`; }
function accounts() { const groups = ['asset','liability']; return `<div class="toolbar">${sortSelect('accounts',[['name','Name'],['institution','Institution'],['balance','Balance'],['type','Type']])}</div>${groups.map((group) => {const items=sorted(data.accounts.filter((a)=>a.group===group&&!a.archived),'accounts',{balance:(a)=>money(a.balance)});return `<section class="account-section"><div class="section-head"><h2>${group === 'asset' ? 'Assets' : 'Liabilities'}</h2><strong>${fmt(items.reduce((s,a)=>s+money(a.balance),0n))}</strong></div>${items.length ? `<div class="account-grid">${items.map((a)=>`<article class="account-card" style="--account-color:${esc(a.color)}"><div class="account-card-head"><span class="account-logo">${icon('wallet')}</span>${overflowMenu('accounts',a.id,a.name)}</div><div><p class="account-institution">${esc(a.institution)}</p><h3>${esc(a.name)}</h3><p class="account-meta">${esc(a.type)} · ${esc(a.mask)}</p></div><div class="account-card-balance"><span>Current balance</span><strong>${amt(a.balance,a.currency)}</strong></div><p class="account-updated">Last updated ${esc(a.updatedAt?new Intl.DateTimeFormat(data.settings.locale,{dateStyle:'medium'}).format(new Date(a.updatedAt)):'when last edited')}</p></article>`).join('')}</div>` : `<div class="compact-empty card"><div><strong>No ${group==='asset'?'asset':'liability'} accounts</strong><p class="muted small">Add one to include it in balances and net worth.</p></div><button class="button small" data-add="accounts">Add ${group==='asset'?'asset':'liability'}</button></div>`}</section>`;}).join('')}`; }
function transactionsPage() { const filtered = periodTransactions().filter((t) => [t.description,t.merchant,get('accounts',t.accountId)?.name,get('categories',t.categoryId)?.name].some((v)=>String(v||'').toLowerCase().includes(search.toLowerCase()))); return `<div class="toolbar transaction-toolbar"><input id="search" value="${esc(search)}" placeholder="Search ${esc(periodLabel())} transactions…" aria-label="Search transactions"><button class="button" data-action="csv-export">Export CSV</button><label class="button">Import CSV<input type="file" id="csv-import" accept=".csv,text/csv" hidden></label></div>${card(transactionTable(filtered),'transactions-card')}`; }
function budgetRows(compact=false) { const budgets=data.budgets.filter((budget)=>budget.period===selectedMonth); if (!budgets.length) return `<div class="compact-empty"><div><strong>No plan for ${esc(periodLabel())}</strong><p class="muted small">Add a category budget or copy the prior month.</p></div><button class="button small" data-add="budgets">Add budget</button></div>`; return budgets.slice(0,compact?4:999).map((b) => { const spent=periodTransactions().filter((t)=>t.categoryId===b.categoryId&&t.type==='expense').reduce((s,t)=>s+money(t.amount),0n); const p=budgetProgress(b.amount,decimal(spent),b.warning),name=get('categories',b.categoryId)?.name||'Category'; return `<div class="budget-row"><div class="budget-row-head"><div><strong>${esc(name)}</strong><span class="badge ${p.status}">${pct(p.used)}</span></div>${compact?'':overflowMenu('budgets',b.id,`${name} budget`)}</div>${progress(Number(p.used)/100,p.status)}<div class="budget-values"><span><small>Spent</small>${fmt(spent)}</span><span><small>Plan</small>${amt(b.amount)}</span><span class="${p.remaining<0n?'expense':''}"><small>${p.remaining<0n?'Over':'Remaining'}</small>${fmt(p.remaining<0n?-p.remaining:p.remaining)}</span></div></div>`; }).join(''); }
function budgetPage() { return `<div class="toolbar"><button class="button" data-action="copy-budget">Copy previous month</button></div>${card(`<div class="section-head"><div><h2>Monthly plan</h2><span class="small muted">Forecasts update from actual spending</span></div></div>${budgetRows()}`,'budget-card')}`; }
function billList(compact=false) { const bills=sorted(data.bills,'bills',{amount:(b)=>money(b.amount),paid:(b)=>b.paid?1:0}).slice(0,compact?4:999); return bills.length ? `<div class="list">${bills.map((b)=>`<div class="list-item bill-item"><span class="avatar">▤</span><div><div class="item-title">${esc(b.name)}</div><div class="item-meta">${esc(b.frequency)} · due ${esc(b.dueDate)} · ${b.autopay?'Auto-pay':'Manual'}</div></div><div><div class="amount">${amt(b.amount,b.currency)}</div><div class="actions">${b.paid?'<span class="badge healthy">Paid</span>':`<button class="button small primary" data-action="pay-bill" data-id="${esc(b.id)}">Mark paid</button>`}${compact?'':overflowMenu('bills',b.id,b.name,`<button type="button" data-action="skip-bill" data-id="${esc(b.id)}" role="menuitem"><strong>Skip this occurrence</strong><span>Move to the next due date</span></button>`)}</div></div></div>`).join('')}</div>` : `<div class="compact-empty"><div><strong>No upcoming bills</strong><p class="muted small">Add recurring commitments to see them in your forecast.</p></div><button class="button small" data-add="bills">Add bill</button></div>`; }
function bills() { return `<div class="toolbar"><a class="button" href="#/calendar">Calendar view</a>${sortSelect('bills',[['dueDate','Due date'],['name','Name'],['amount','Amount'],['paid','Payment status']])}</div>${card(billList())}`; }
function goalCards(compact=false) { const priorities={high:1,medium:2,low:3}; const goals=sorted(data.goals.filter((g)=>!g.archived),'goals',{priority:(g)=>priorities[g.priority]||4,progress:(g)=>goalProjection(g.current,g.target,g.monthly).completion}).slice(0,compact?3:999); return goals.length ? goals.map((g)=>{const p=goalProjection(g.current,g.target,g.monthly); return `<div class="list-item"><span class="avatar" style="color:${esc(g.color)}">${esc(g.icon)}</span><div><div class="item-title">${esc(g.name)}</div><div class="item-meta">${amt(g.current)} saved · ${p.months===null?'Contribution needed':`${p.months} months estimated`}</div>${progress(Number(p.completion)/100)}</div><strong>${pct(p.completion)}</strong></div>`;}).join('') : empty('goals'); }
function goals() { return `<div class="toolbar"><button class="button primary" data-add="goals">＋ Add goal</button>${sortSelect('goals',[['priority','Priority'],['name','Name'],['targetDate','Target date'],['progress','Progress']])}</div>${card(goalCards())}`; }
function investments() { let holdings=data.holdings.map((h)=>({...h,...investmentGain(h.quantity,h.averageCost,h.currentPrice)})); const value=holdings.reduce((s,h)=>s+h.value,0n),gain=holdings.reduce((s,h)=>s+h.gain,0n); holdings=sorted(holdings,'investments',{quantity:(h)=>money(h.quantity),currentPrice:(h)=>money(h.currentPrice),value:(h)=>h.value,gain:(h)=>h.gain}); return `<div class="grid summary-grid">${card(`<span class="metric-label">Portfolio value</span><div class="metric"><strong>${fmt(value)}</strong></div>`)}${card(`<span class="metric-label">Total gain / loss</span><div class="metric"><strong class="${gain<0n?'expense':'income'}">${fmt(gain)}</strong></div>`)}${card(`<span class="metric-label">Dividend income</span><div class="metric"><strong>${fmt(data.holdings.reduce((s,h)=>s+money(h.dividends||'0'),0n))}</strong></div>`)}</div><br><div class="toolbar"><button class="button primary" data-add="holdings">＋ Add holding</button></div>${card(holdings.length?`<div class="table-wrap"><table><thead><tr><th>${sortButton('investments','name','Holding')}</th><th>${sortButton('investments','assetClass','Class')}</th><th>${sortButton('investments','quantity','Quantity')}</th><th>${sortButton('investments','currentPrice','Price')}</th><th>${sortButton('investments','value','Value')}</th><th>${sortButton('investments','gain','Gain')}</th></tr></thead><tbody>${holdings.map(h=>`<tr><td><strong>${esc(h.name)}</strong><div class="item-meta">${esc(h.symbol)}</div></td><td>${esc(h.assetClass)}</td><td>${esc(h.quantity)}</td><td>${amt(h.currentPrice,h.currency)}</td><td>${fmt(h.value,h.currency)}</td><td class="${h.gain<0n?'expense':'income'}">${fmt(h.gain,h.currency)}</td></tr>`).join('')}</tbody></table></div>`:empty('holdings'))}`; }
function netWorthPage() { const worth=netWorth(data.accounts,data.settings.rates); return `<div class="grid summary-grid">${card(`<span class="metric-label">Current net worth</span><div class="metric"><strong>${fmt(worth)}</strong></div>`)}${card(`<span class="metric-label">Included accounts</span><div class="metric"><strong>${data.accounts.filter(a=>a.includeNetWorth).length}</strong></div>`)}</div><br>${card(`<div class="section-head"><h2>Account contribution</h2><span class="small muted">Reporting currency: ${esc(data.settings.primaryCurrency)}</span></div>${data.accounts.filter(a=>a.includeNetWorth).map(a=>`<div class="bar-row"><span>${esc(a.name)}</span>${progress(Math.abs(Number(money(a.balance)*100n/(worth||1n))))}<strong class="${a.group==='liability'?'expense':''}">${a.group==='liability'?'−':''}${amt(a.balance,a.currency)}</strong></div>`).join('')}`)}`; }
function reports() { const transactions=periodTransactions(),cf=cashFlow(transactions),history=monthlyHistory(12),previous=history.at(-2);const expenses=transactions.filter(t=>t.type==='expense'&&t.status!=='pending');const categoryRows=data.categories.map(c=>({name:c.name,total:expenses.filter(t=>t.categoryId===c.id).reduce((s,t)=>s+money(t.amount),0n)})).filter(c=>c.total).sort((a,b)=>compare(b.total,a.total));const merchants=[...new Set(expenses.map(t=>t.merchant||t.description))].map(name=>({name,total:expenses.filter(t=>(t.merchant||t.description)===name).reduce((s,t)=>s+money(t.amount),0n),count:expenses.filter(t=>(t.merchant||t.description)===name).length})).sort((a,b)=>compare(b.total,a.total));const recurring=[...new Set(data.transactions.filter(t=>t.type==='expense').map(t=>t.merchant||t.description))].map(name=>{const rows=data.transactions.filter(t=>t.type==='expense'&&(t.merchant||t.description)===name);return {name,count:rows.length,average:rows.length?rows.reduce((s,t)=>s+money(t.amount),0n)/BigInt(rows.length):0n};}).filter(x=>x.count>=2).sort((a,b)=>b.count-a.count);const budgeted=data.budgets.filter(b=>b.period===selectedMonth).reduce((s,b)=>s+money(b.amount),0n),variance=budgeted-cf.expenses;return `<div class="toolbar"><button class="button" onclick="print()">Print</button><button class="button" data-action="csv-export">Export CSV</button></div><div class="grid summary-grid">${card(`<span class="metric-label">Income</span><div class="metric"><strong>${fmt(cf.income)}</strong>${previous?changeLabel(cf.income,previous.income):''}</div>`)}${card(`<span class="metric-label">Expenses</span><div class="metric"><strong>${fmt(cf.expenses)}</strong>${previous?changeLabel(cf.expenses,previous.expenses,true):''}</div>`)}${card(`<span class="metric-label">Savings rate</span><div class="metric"><strong>${pct(savingsRateMinor(cf))}</strong></div>`)}${card(`<span class="metric-label">Budget variance</span><div class="metric"><strong class="${variance<0n?'expense':'income'}">${fmt(variance)}</strong></div>`)}</div><div class="analytics-grid">${card(`<div class="section-head"><div><h2>Income and spending trend</h2><span class="small muted">12 financial periods</span></div></div><div class="trend-chart" role="img" aria-label="Monthly income and expenses">${history.map(row=>`<div><span>${esc(row.month.slice(5))}</span><i><b style="height:${Math.max(2,Number(ratio(row.income,history.reduce((m,x)=>x.income>m?x.income:m,1n)))/100)}%"></b><em style="height:${Math.max(2,Number(ratio(row.expenses,history.reduce((m,x)=>x.expenses>m?x.expenses:m,1n)))/100)}%"></em></i></div>`).join('')}</div><div class="chart-legend"><span><i class="income-key"></i>Income</span><span><i class="expense-key"></i>Expenses</span></div>`,'analytics-wide')}${card(`<div class="section-head"><h2>Category analysis</h2></div>${categoryRows.length?categoryRows.slice(0,8).map(c=>`<div class="bar-row category-row"><span>${esc(c.name)}</span>${progress(Number(ratio(c.total,cf.expenses))/100)}<strong>${fmt(c.total)}</strong></div>`).join(''):empty('category activity')}`)}${card(`<div class="section-head"><h2>Top merchants</h2></div>${merchants.length?`<div class="ranked-list">${merchants.slice(0,8).map((m,index)=>`<div><span>${index+1}</span><p><strong>${esc(m.name)}</strong><small>${m.count} transaction${m.count===1?'':'s'}</small></p><strong>${fmt(m.total)}</strong></div>`).join('')}</div>`:empty('merchant activity')}`)}${card(`<div class="section-head"><div><h2>Subscriptions & recurring</h2><span class="small muted">Detected from repeated merchants</span></div></div>${recurring.length?`<div class="ranked-list">${recurring.slice(0,8).map(item=>`<div><span>↻</span><p><strong>${esc(item.name)}</strong><small>${item.count} recorded payments</small></p><strong>~${fmt(item.average)}</strong></div>`).join('')}</div>`:empty('recurring payments')}`)}${card(`<div class="section-head"><h2>Budget performance</h2></div><div class="variance"><span>Planned <strong>${fmt(budgeted)}</strong></span><span>Spent <strong>${fmt(cf.expenses)}</strong></span><span class="${variance<0n?'expense':'income'}">${variance<0n?'Over':'Remaining'} <strong>${fmt(variance<0n?-variance:variance)}</strong></span></div>${progress(budgeted?Number(ratio(cf.expenses,budgeted))/100:0,variance<0n?'exceeded':'healthy')}`)}${card(`<div class="section-head"><h2>Net-worth history</h2></div><div class="compact-empty"><div><strong>${fmt(netWorth(data.accounts,data.settings.rates))} today</strong><p class="muted small">Historical account snapshots are not available yet. Quiet Ledger will not infer or fabricate past balances.</p></div><a class="button small" href="#/net-worth">View accounts</a></div>`)}</div>`; }
function calendar() { const [year,monthNumber]=selectedMonth.split('-').map(Number),month=monthNumber-1,first=new Date(year,month,1).getDay(),days=new Date(year,month+1,0).getDate(); const cells=Array.from({length:first},()=>'<div></div>').concat(Array.from({length:days},(_,i)=>{const day=i+1,events=data.bills.filter(b=>inPeriod(b,'dueDate')&&new Date(`${b.dueDate}T12:00:00`).getDate()===day);return `<div class="day"><strong>${day}</strong>${events.map(e=>`<span class="event">${esc(e.name)} · ${amt(e.amount,e.currency)}</span>`).join('')}</div>`;})); return `<div class="toolbar"><button class="button">Month</button><button class="button">Week</button><button class="button">Agenda</button><button class="button primary" data-add="bills">＋ Event</button></div>${card(`<div class="section-head"><h2>${esc(periodLabel())}</h2></div><div style="overflow:auto"><div class="calendar">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="calendar-head">${d}</div>`).join('')}${cells.join('')}</div></div>`)}`; }
function loans() { const items=sorted(data.loans,'loans',{balance:(l)=>money(l.balance),annualRate:(l)=>money(l.annualRate),monthlyPayment:(l)=>money(l.monthlyPayment)}); return `<div class="toolbar"><button class="button primary" data-add="loans">＋ Add loan</button>${sortSelect('loans',[['name','Name'],['balance','Balance'],['annualRate','Interest rate'],['monthlyPayment','Monthly payment']])}</div>${items.length?items.map(l=>{let result;try{result=amortize({principal:l.balance,annualRate:l.annualRate,monthlyPayment:l.monthlyPayment,extraPayment:l.extraPayment});}catch(e){result={schedule:[],totalInterest:0n};}return card(`<div class="section-head"><div><h2>${esc(l.name)}</h2><span class="small muted">${esc(l.lender)} · ${esc(l.annualRate)}% ${esc(l.interestType)}</span></div><button class="button" data-edit="loans" data-id="${l.id}">Edit</button></div><div class="grid summary-grid"><div><span class="metric-label">Balance</span><p class="amount" style="text-align:left">${amt(l.balance)}</p></div><div><span class="metric-label">Monthly payment</span><p class="amount" style="text-align:left">${amt(l.monthlyPayment)}</p></div><div><span class="metric-label">Payments left</span><p class="amount" style="text-align:left">${result.schedule.length}</p></div><div><span class="metric-label">Projected interest</span><p class="amount expense" style="text-align:left">${fmt(result.totalInterest)}</p></div></div>`);}).join('<br>'):empty('loans')}`; }
function settings() { const s=data.settings; return `<form id="settings-form" class="settings-grid">${card(`<div class="section-head"><h2>General</h2></div>${field('Locale','locale','text',s.locale)}${field('Time zone','timezone','text',s.timezone)}`)}${card(`<div class="section-head"><h2>Financial period</h2></div><div class="field"><label for="f-monthStart">Financial month starts (1–28)</label><input id="f-monthStart" name="monthStart" type="number" min="1" max="28" step="1" value="${esc(s.monthStart)}" required></div><p class="small muted">With day 25, August covers July 25 through August 24.</p>`)}${card(`<div class="section-head"><h2>Currency & appearance</h2></div>${field('Primary currency','primaryCurrency','select',s.primaryCurrency,s.currencies.map(c=>[c,c]))}${field('Theme','theme','select',s.theme,[['system','System'],['light','Light'],['dark','Dark']])}`)}${card(`<div class="section-head"><h2>Budget defaults</h2></div><div class="field"><label for="f-budgetWarning">Warning threshold (%)</label><input id="f-budgetWarning" name="budgetWarning" type="number" min="1" max="100" step="1" value="${esc(s.budgetWarning)}" required></div>`)}<div class="settings-save"><span class="small muted" id="settings-status" aria-live="polite">Changes are saved to MySQL.</span><button class="button primary">Save preferences</button></div></form><div class="grid two-col settings-secondary">${card(`<div class="section-head"><h2>Dashboard widgets</h2></div><div class="list">${Object.entries(summaryMetrics()).map(([key,value])=>`<label class="list-item"><input type="checkbox" data-widget="${key}" ${data.widgets.includes(key)?'checked':''}><span>${esc(value[0])}</span></label>`).join('')}</div>`)}${card(`<div class="section-head"><h2>Categories</h2><button class="button" data-add="categories">＋ Add</button></div>${data.categories.map(c=>`<div class="list-item"><span class="avatar" style="color:${esc(c.color)}">${esc(c.icon)}</span><div><div class="item-title">${esc(c.name)}</div><div class="item-meta">${esc(c.type)}</div></div><button class="button small" data-edit="categories" data-id="${c.id}">Edit</button></div>`).join('')}`)}${card(`<div class="section-head"><h2>Import, backup & privacy</h2></div><div class="callout">Backups include private financial data. Store exported files securely.</div><div class="actions" style="margin-top:16px"><button class="button" data-action="backup">Export backup</button><label class="button">Restore<input id="restore" type="file" accept="application/json" hidden></label><button class="button" data-action="demo">Restore demo</button><button class="button danger" data-action="clear">Clear data</button></div>`)}</div>`; }
function assistantAnswer(question) { const q=question.toLowerCase(),cf=cashFlow(periodTransactions()),history=monthlyHistory(),previous=history.at(-2),expenses=periodTransactions().filter(t=>t.type==='expense'&&t.status!=='pending'),categories=data.categories.map(c=>({name:c.name,total:expenses.filter(t=>t.categoryId===c.id).reduce((s,t)=>s+money(t.amount),0n)})).sort((a,b)=>compare(b.total,a.total)),top=categories[0];if(q.includes('save')||q.includes('forecast')){const monthly=cf.income-cf.expenses;return monthly>0n?`At this period's pace, you retain ${fmt(monthly)} per month and about ${fmt(monthly*12n)} over 12 months, before interest or one-off changes.`:`This period has a ${fmt(-monthly)} shortfall. A positive savings forecast requires reducing expenses or increasing cleared income.`;}if(q.includes('increase')||q.includes('compare'))return previous?`Expenses are ${fmt(cf.expenses)} this period versus ${fmt(previous.expenses)} in ${previous.label}, a change of ${pct(periodChange(cf.expenses,previous.expenses).percent)}.`:'There is not enough prior-period activity for a reliable comparison.';if(q.includes('category')||q.includes('spend')||q.includes('expense'))return top&&top.total>0n?`${top.name} is your largest expense category this period at ${fmt(top.total)}, representing ${pct(ratio(top.total,cf.expenses))} of cleared expenses.`:'No cleared expenses were recorded in this financial period.';if(q.includes('bill')){const open=data.bills.filter(b=>!b.paid);return open.length?`${open.length} bill${open.length===1?' is':'s are'} open, totaling ${fmt(open.reduce((s,b)=>s+money(b.amount),0n))}. The next due date is ${open.sort((a,b)=>a.dueDate.localeCompare(b.dueDate))[0].dueDate}.`:'All recorded bills are marked paid.';}return `For ${periodLabel()}, cleared income is ${fmt(cf.income)}, expenses are ${fmt(cf.expenses)}, and the savings rate is ${pct(savingsRateMinor(cf))}. Try asking about spending, comparisons, bills, or savings forecasts.`; }
function assistant() { const cf=cashFlow(periodTransactions()),history=monthlyHistory(),previous=history.at(-2),insights=financialInsights(cf,previous),forecast=cf.income-cf.expenses;return `<div class="assistant-hero"><div><span class="badge healthy">Private on-device analysis</span><h2>Your financial copilot</h2><p>Quiet Ledger analyzes only the records already stored in your dashboard. It does not send financial data to an external AI service.</p></div><div class="assistant-forecast"><span>12-month savings forecast</span><strong class="${forecast<0n?'expense':'income'}">${fmt(forecast*12n)}</strong><small>Based on this period's cleared cash flow</small></div></div><div class="grid assistant-grid">${card(`<div class="section-head"><h2>Briefing for ${esc(periodLabel())}</h2></div><div class="insights-list">${insights.slice(0,4).map(item=>`<div class="insight ${item.tone}"><span>${item.icon}</span><div><strong>${esc(item.title)}</strong><p>${esc(item.detail)}</p></div></div>`).join('')}</div>`)}${card(`<div class="section-head"><h2>Ask Quiet Ledger</h2></div><form id="assistant-form"><label for="assistant-question">Question about your finances</label><div class="assistant-input"><input id="assistant-question" name="question" value="${esc(assistantQuestion)}" placeholder="Where did my spending increase?" required><button class="button primary">Ask</button></div></form>${assistantQuestion?`<div class="assistant-answer" aria-live="polite"><span class="avatar">Q</span><p>${esc(assistantAnswer(assistantQuestion))}</p></div>`:`<div class="question-chips"><button data-action="assistant-prompt" data-question="Where did my spending increase?">Compare spending</button><button data-action="assistant-prompt" data-question="How much can I save?">Forecast savings</button><button data-action="assistant-prompt" data-question="What bills are due?">Review bills</button></div>`}`)}</div>`; }
function renderPage(page) { return ({overview,accounts,transactions:transactionsPage,budget:budgetPage,bills,goals,investments,'net-worth':netWorthPage,reports,calendar,loans,settings,assistant}[page] || overview)(); }

const forms = {
  accounts: (x={}) => `${field('Account name','name','text',x.name)}${field('Institution','institution','text',x.institution)}${field('Type','type','select',x.type||'current',[['current','Current'],['savings','Savings'],['cash','Cash'],['credit-card','Credit card'],['fixed-deposit','Fixed deposit'],['investment','Investment'],['loan','Loan'],['mortgage','Mortgage'],['vehicle-loan','Vehicle loan'],['wallet','Digital wallet'],['other-asset','Other asset'],['other-liability','Other liability']])}${field('Group','group','select',x.group||'asset',[['asset','Asset'],['liability','Liability']])}${field('Currency','currency','select',x.currency||data.settings.primaryCurrency,data.settings.currencies.map(c=>[c,c]))}${field('Balance','balance','number',x.balance||'0.00')}${field('Masked number','mask','text',x.mask||'•••• 0000')}${field('Colour','color','color',x.color||'#24745b')}<div class="field span-2"><label><input type="checkbox" name="includeNetWorth" ${x.includeNetWorth!==false?'checked':''}> Include in net worth</label></div>`,
  transactions: (x={}) => `${field('Date','date','date',x.date||`${selectedMonth}-01`)}${field('Description','description','text',x.description)}${field('Merchant','merchant','text',x.merchant)}${field('Amount','amount','number',x.amount||'0.00')}${field('Currency','currency','select',x.currency||data.settings.primaryCurrency,data.settings.currencies.map(c=>[c,c]))}${field('Type','type','select',x.type||'expense',[['income','Income'],['expense','Expense'],['transfer','Transfer'],['refund','Refund']])}${field('Account','accountId','select',x.accountId||'',data.accounts.map(a=>[a.id,a.name]))}${field('Category','categoryId','select',x.categoryId||'',[['','Uncategorized'],...data.categories.map(c=>[c.id,c.name])])}${field('Status','status','select',x.status||'cleared',[['cleared','Cleared'],['pending','Pending'],['reconciled','Reconciled']])}`,
  budgets: (x={}) => `${field('Category','categoryId','select',x.categoryId||'',data.categories.filter(c=>c.type==='expense').map(c=>[c.id,c.name]))}${field('Budget amount','amount','number',x.amount||'0.00')}${field('Period','period','month',x.period||selectedMonth)}${field('Method','method','select',x.method||'standard',[['standard','Non-rollover'],['rollover','Rollover'],['zero-based','Zero-based']])}${field('Warning threshold %','warning','number',x.warning||data.settings.budgetWarning)}`,
  bills: (x={}) => `${field('Bill name','name','text',x.name)}${field('Payee','payee','text',x.payee)}${field('Amount','amount','number',x.amount||'0.00')}${field('Currency','currency','select',x.currency||data.settings.primaryCurrency,data.settings.currencies.map(c=>[c,c]))}${field('Frequency','frequency','select',x.frequency||'monthly',[['weekly','Weekly'],['biweekly','Every two weeks'],['monthly','Monthly'],['bimonthly','Every two months'],['quarterly','Quarterly'],['semiannual','Every six months'],['annual','Annually'],['custom','Custom']])}${field('Due date','dueDate','date',x.dueDate||new Date().toISOString().slice(0,10))}${field('Account','accountId','select',x.accountId||'',data.accounts.map(a=>[a.id,a.name]))}${field('Reminder days','reminder','number',x.reminder||3)}<div class="field"><label><input type="checkbox" name="autopay" ${x.autopay?'checked':''}> Auto-pay</label></div>`,
  goals: (x={}) => `${field('Goal name','name','text',x.name)}${field('Description','description','text',x.description)}${field('Target amount','target','number',x.target||'0.00')}${field('Current saved','current','number',x.current||'0.00')}${field('Monthly contribution','monthly','number',x.monthly||'0.00')}${field('Target date','targetDate','date',x.targetDate||new Date().toISOString().slice(0,10))}${field('Priority','priority','select',x.priority||'medium',[['low','Low'],['medium','Medium'],['high','High']])}${field('Colour','color','color',x.color||'#24745b')}`,
  holdings: (x={}) => `${field('Name','name','text',x.name)}${field('Symbol','symbol','text',x.symbol)}${field('Asset class','assetClass','text',x.assetClass)}${field('Quantity','quantity','number',x.quantity||'0.00')}${field('Average cost','averageCost','number',x.averageCost||'0.00')}${field('Current price','currentPrice','number',x.currentPrice||'0.00')}${field('Currency','currency','select',x.currency||data.settings.primaryCurrency,data.settings.currencies.map(c=>[c,c]))}${field('Dividends','dividends','number',x.dividends||'0.00')}`,
  loans: (x={}) => `${field('Loan name','name','text',x.name)}${field('Lender','lender','text',x.lender)}${field('Original principal','principal','number',x.principal||'0.00')}${field('Current balance','balance','number',x.balance||'0.00')}${field('Annual interest %','annualRate','number',x.annualRate||'0')}${field('Monthly payment','monthlyPayment','number',x.monthlyPayment||'0.00')}${field('Extra payment','extraPayment','number',x.extraPayment||'0.00')}${field('Interest type','interestType','select',x.interestType||'reducing',[['reducing','Reducing balance'],['flat','Flat']])}`,
  categories: (x={}) => `${field('Category name','name','text',x.name)}${field('Type','type','select',x.type||'expense',[['expense','Expense'],['income','Income']])}${field('Icon','icon','text',x.icon||'○')}${field('Colour','color','color',x.color||'#24745b')}${field('SMS matching keywords','smsKeywords','text',Array.isArray(x.smsKeywords)?x.smsKeywords.join(', '):(x.smsKeywords||''))}`
};
function modal(resource,id='',defaults={}) { const existing=id?get(resource,id):defaults; const label=resource[0].toUpperCase()+resource.slice(1,-1); document.body.insertAdjacentHTML('beforeend',`<div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><section class="modal-card"><div class="section-head"><h2 id="modal-title">${id?'Edit':'Add'} ${esc(label)}</h2><button class="button icon-button" data-close aria-label="Close">×</button></div>${defaults.importSource === 'banking-sms' ? '<div class="callout">Review the parsed details before saving. The SMS was processed locally.</div>' : ''}<form id="entity-form" data-resource="${resource}" data-id="${id}" class="form-grid">${forms[resource](existing)}${defaults.rawSms ? `<input type="hidden" name="rawSms" value="${esc(defaults.rawSms)}"><input type="hidden" name="importSource" value="banking-sms">` : ''}<div class="actions span-2"><button class="button primary" type="submit">Save</button>${id?'<button class="button danger" type="button" data-delete>Delete</button>':''}<button class="button" type="button" data-close>Cancel</button></div></form></section></div>`); document.querySelector('.modal input:not([type="hidden"])')?.focus(); }
async function smsModal() { let clipboard=''; try { clipboard=await navigator.clipboard?.readText() || ''; } catch { clipboard=''; } document.body.insertAdjacentHTML('beforeend',`<div class="modal" role="dialog" aria-modal="true" aria-labelledby="sms-title"><section class="modal-card"><div class="section-head"><div><h2 id="sms-title">Import banking SMS</h2><span class="small muted">Parsed privately in your browser</span></div><button class="button icon-button" data-close aria-label="Close">×</button></div><form id="sms-form"><div class="field"><label for="banking-sms">Online banking message</label><textarea id="banking-sms" name="sms" rows="7" maxlength="2000" placeholder="Paste a debit or credit notification…" required>${esc(clipboard)}</textarea></div><div class="callout" style="margin-top:14px">No message content is sent to a bank or AI service. Verify the amount, account, and category on the next screen.</div><div class="actions" style="margin-top:18px"><button class="button primary" type="submit">Analyze SMS</button><button class="button" type="button" data-close>Cancel</button></div></form></section></div>`); document.querySelector('#banking-sms').focus(); }
function formValues(form) { const values=Object.fromEntries(new FormData(form)); form.querySelectorAll('input[type=checkbox]').forEach(i=>values[i.name]=i.checked); return values; }
function csv() { const header=['date','description','merchant','amount','currency','account','category','type','status']; const quote=v=>`"${String(v??'').replaceAll('"','""')}"`; return [header.join(','),...periodTransactions().map(t=>[t.date,t.description,t.merchant,t.amount,t.currency,get('accounts',t.accountId)?.name,get('categories',t.categoryId)?.name,t.type,t.status].map(quote).join(','))].join('\n'); }
function moveMonth(offset) { const [year,month]=selectedMonth.split('-').map(Number); const next=new Date(Date.UTC(year,month-1+offset,1)); selectedMonth=next.toISOString().slice(0,7); sessionStorage.setItem('harbor-finance-period',selectedMonth); render(); }
function copyPreviousBudget() { const sourcePeriod=reportingMonthOffset(selectedMonth,-1),source=data.budgets.filter((budget)=>budget.period===sourcePeriod); if(!source.length){toast(`No budgets found for ${monthLabel(sourcePeriod)}`);return;} const existing=new Set(data.budgets.filter((budget)=>budget.period===selectedMonth).map((budget)=>budget.categoryId)),copies=source.filter((budget)=>!existing.has(budget.categoryId)).map((budget)=>({...budget,id:`budg-${uniqueId()}`,period:selectedMonth})); if(!copies.length){toast(`${periodLabel()} already has budgets for every previous category`);return;} data.budgets=[...data.budgets,...copies];repo.save(data);render();toast(`${copies.length} budget${copies.length===1?'':'s'} copied from ${monthLabel(sourcePeriod)}`); }
function render() { data=repo.load(); applyTheme(); shell(route()); }

document.addEventListener('submit',(event)=>{ event.preventDefault(); const form=event.target;
  try { if(form.id==='assistant-form'){assistantQuestion=String(new FormData(form).get('question')||'').trim();render();return;}if(form.id==='sms-form'){const parsed=parseBankingSms(new FormData(form).get('sms'),{accounts:data.accounts,categories:data.categories,primaryCurrency:data.settings.primaryCurrency});form.closest('.modal').remove();modal('transactions','',parsed);return;} if(form.id==='entity-form'){const values=formValues(form); ['amount','balance','target','current','monthly','principal','monthlyPayment','extraPayment','averageCost','currentPrice','dividends','quantity'].forEach(k=>{if(k in values) money(values[k]);}); const resource=form.dataset.resource,id=form.dataset.id; if(resource==='accounts'){values.archived=false;values.updatedAt=new Date().toISOString();} if(resource==='categories') values.smsKeywords=String(values.smsKeywords||'').split(',').map((value)=>value.trim()).filter(Boolean); if(resource==='bills') values.paid=get(resource,id)?.paid||false; if(resource==='goals'){values.archived=false;values.icon=get(resource,id)?.icon||'◎';values.type=get(resource,id)?.type||'custom';} id?repo.update(resource,id,values):repo.create(resource,values); document.querySelector('.modal').remove(); render(); toast(`${resource.slice(0,-1)} saved`); return;} if(form.id==='settings-form'){const v=formValues(form),monthStart=Number(v.monthStart),budgetWarning=Number(v.budgetWarning);financialPeriod(selectedMonth,monthStart);if(!Number.isInteger(budgetWarning)||budgetWarning<1||budgetWarning>100) throw new Error('Warning threshold must be from 1 to 100.');data.settings={...data.settings,...v,monthStart,budgetWarning};repo.save(data);render();toast('Preferences saved');} } catch(error){toast(error.message);} });
document.addEventListener('click',(event)=>{const target=event.target.closest('[data-action],[data-add],[data-edit],[data-close],[data-delete],[data-sort-page],[data-list-direction]');if(!target)return;
  if(target.dataset.sortPage){const state=sortState[target.dataset.sortPage];state.direction=state.key===target.dataset.sortKey?(state.direction==='asc'?'desc':'asc'):'asc';state.key=target.dataset.sortKey;if(target.dataset.sortPage==='transactions')transactionPage=1;render();return;} if(target.dataset.listDirection){const state=sortState[target.dataset.listDirection];state.direction=state.direction==='asc'?'desc':'asc';render();return;}
  if(target.dataset.close!==undefined){target.closest('.modal').remove();return;} if(target.dataset.add){target.closest('details')?.removeAttribute('open');const defaults=target.dataset.add==='transactions'&&target.dataset.transactionType?{type:target.dataset.transactionType}:{};modal(target.dataset.add,'',defaults);return;} if(target.dataset.edit){target.closest('details')?.removeAttribute('open');modal(target.dataset.edit,target.dataset.id);return;} if(target.dataset.delete!==undefined){const form=target.closest('form');if(confirm('Delete this record? This cannot be undone.')){repo.remove(form.dataset.resource,form.dataset.id);target.closest('.modal').remove();render();}return;}
  const action=target.dataset.action;if(action==='previous-month'){transactionPage=1;moveMonth(-1);} if(action==='next-month'){transactionPage=1;moveMonth(1);} if(action==='current-month'){transactionPage=1;selectedMonth=new Date().toISOString().slice(0,7);sessionStorage.setItem('harbor-finance-period',selectedMonth);render();} if(action==='transaction-page'){transactionPage=Number(target.dataset.page);render();} if(action==='sms-import'){target.closest('.action-menu')?.removeAttribute('open');smsModal();} if(action==='pay-bill'){const bill=get('bills',target.dataset.id);repo.update('bills',bill.id,{paid:true});render();toast('Bill marked paid');} if(action==='skip-bill'){const bill=get('bills',target.dataset.id);repo.update('bills',bill.id,{dueDate:nextOccurrence(bill.dueDate,bill.frequency),paid:false});render();toast('Bill moved to its next due date');}if(action==='assistant-prompt'){assistantQuestion=target.dataset.question;render();} if(action==='csv-export')download(`transactions-${selectedMonth}.csv`,csv(),'text/csv'); if(action==='backup')download(`quiet-ledger-backup-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(data,null,2)); if(action==='demo'&&confirm('Replace current data with removable demo data?')){repo.clear(true);render();} if(action==='clear'&&confirm('Delete all local financial data? Export a backup first if needed.')){repo.clear(false);render();} if(action==='copy-budget')copyPreviousBudget();
});
document.addEventListener('click',(event)=>{document.querySelectorAll('.action-menu[open],.overflow-menu[open],.quick-add[open]').forEach((menu)=>{if(!menu.contains(event.target))menu.removeAttribute('open');});});
document.addEventListener('keydown',(event)=>{if(event.key==='Escape')document.querySelectorAll('details[open]').forEach((menu)=>menu.removeAttribute('open'));});
document.addEventListener('input',(event)=>{if(event.target.id==='search'){search=event.target.value;transactionPage=1;document.querySelector('#page').innerHTML=transactionsPage();} if(event.target.dataset.widget){const key=event.target.dataset.widget;data.widgets=event.target.checked?[...new Set([...data.widgets,key])]:data.widgets.filter(x=>x!==key);repo.save(data);}});
document.addEventListener('change',async(event)=>{if(event.target.dataset.listSort){sortState[event.target.dataset.listSort].key=event.target.value;render();} if(event.target.id==='transaction-page-size'||event.target.id==='transaction-page-size-toolbar'){transactionPageSize=Number(event.target.value);transactionPage=1;render();} if(event.target.id==='period-month'&&/^\d{4}-\d{2}$/.test(event.target.value)){transactionPage=1;selectedMonth=event.target.value;sessionStorage.setItem('harbor-finance-period',selectedMonth);render();} if(event.target.id==='restore'){try{repo.replace(JSON.parse(await event.target.files[0].text()));render();toast('Backup restored');}catch(error){toast(error.message);}} if(event.target.id==='csv-import'){try{const lines=(await event.target.files[0].text()).trim().split(/\r?\n/);if(lines.length<2)throw new Error('CSV contains no rows');toast('CSV validated. Use backup restore for full-fidelity import.');}catch(error){toast(error.message);}}});
window.addEventListener('hashchange',render); repo.subscribe((next)=>{data=next;}); render();
